INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_anime_panel', 'seed_team_house', 'anime-panel', 'Anime Panel', 'Cel-shaded anime with bold clean lines and big expression. For younger-skewing posts and anything that wants stylised emotion.', 'Modern anime cel shading: flat colour regions with two crisp shadow steps, bold clean outlines that vary subtly in weight, and vivid saturated colour against a softly painted background with atmospheric depth. Expressive lighting — rim light on hair, a bloom on the brightest surface. Composition uses dynamic angles and depth-of-field like a key visual, not a comic page.', 'Drawn as an anime character with proportions kept adult and grounded; hair shape, glasses and build carry the likeness, expressions readable and big.', 'chibi proportions, manga screentone, speech bubbles, photoreal rendering, western cartoon', '["anime","cel-shaded","vivid","stylised"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_aurora_gradient', 'seed_team_house', 'aurora-gradient', 'Aurora Gradient', 'Luminous blurred colour fields with one crisp subject. The classic OG-card background look — brandable, text-friendly, never dates.', 'Large-scale abstract aurora gradient: two or three luminous colour fields blending with extremely soft edges, like light through frosted glass. Fine monochrome noise over the blend to kill banding. The subject is rendered crisp and simple in the foreground against the blur, with strong figure-ground separation. Composition is minimal — one subject, one gradient, vast negative space, no texture or scenery behind.', 'Reduced to a clean simplified figure or silhouette with soft rim light borrowed from the gradient colours, identity carried by outline and hair shape.', 'hard geometric shapes, busy detail, photographic backgrounds, banding, lens flares', '["abstract","gradient","minimal","background"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_cinematic_still', 'seed_team_house', 'cinematic-still', 'Cinematic Still', 'A frame lifted from a film — scene-scale drama where the whole environment acts, not just a face. Use when the story is bigger than a portrait.', 'Widescreen film still with anamorphic character: oval bokeh, gentle horizontal flare, slight edge softness. Dramatic directional key light motivated by something in the scene, atmosphere in the air catching it. Teal-and-amber grade with deep, detailed shadows and restrained highlights, filmic grain and halation. Blocking and set dressing feel production-designed; every prop looks placed on purpose.', 'Photographed as an actor inside the scene — mid-action, lit by the scene''s own sources, face readable but never posed at the camera.', 'flat lighting, centered passport framing, clean digital sharpness, HDR, empty sets', '["photographic","cinematic","dramatic","scene"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_dark_glass', 'seed_team_house', 'dark-glass', 'Dark Glass', 'Moody frosted-glass layers over a deep dark ground — the fintech hero look. Premium, night-mode native.', 'Dark glassmorphism: translucent frosted panes floating in layers over a near-black ground, each pane blurring what sits behind it, with hairline light edges on their top rims. One or two luminous accent glows — electric blue or violet — bleed softly through the glass from behind. Depth comes from stacking and blur radius, not perspective. Surfaces are immaculate; the mood is quiet, expensive, nocturnal.', 'Rendered behind or between the panes as a softly lit figure, partially frosted where glass overlaps, silhouette crisp where it does not.', 'light backgrounds, hard drop shadows, skeuomorphic textures, neon signage, clutter', '["glass","dark","premium","fintech"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_duotone_poster', 'seed_team_house', 'duotone-poster', 'Duotone Poster', 'The whole image mapped to two colours. Forces brand consistency onto any picture; a quiet OG-card favourite.', 'Strict duotone: the entire image tone-mapped to exactly two colours — one deep, one bright — with rich mid-tone blending between them and nothing else. High-contrast poster finish with crisp edges and slightly lifted blacks, composed like a music-venue gig poster: one dominant subject, dramatic scale, flat background field. A whisper of print grain keeps it from feeling digital.', 'A high-contrast duotone portrait treatment — features carved out by the two-colour split, silhouette doing most of the work, unmistakably them at a glance.', 'a third colour, full-colour patches, gradients to white, busy backgrounds, thin details', '["duotone","poster","brandable","graphic"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_faded_film', 'seed_team_house', 'faded-film', 'Faded Film', 'Warm analogue photography that looks pulled from a shoebox of 90s prints. The anti-polish look that reads human in an AI-slick feed.', 'Analogue 35mm colour film photography with pronounced organic grain, slightly faded blacks and a warm expired-film cast — greens shifted olive, highlights creamy, a faint light leak at one edge. Mild vignetting, soft focus falloff, the small framing accidents of a point-and-shoot. Colours are muted but warm, like a print that sat in sunlight for a decade. Nothing is staged-looking; the frame feels found, not made.', 'Photographed candidly on film — natural grain over the skin, caught mid-moment, never posed at the lens.', 'digital sharpness, clean whites, HDR, studio lighting, Instagram-filter teal-orange', '["photographic","film","retro","grain"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_ink_sketchbook', 'seed_team_house', 'ink-sketchbook', 'Ink Sketchbook', 'Loose hand-drawn ink and wash, wobbles included. Signals a human hand in a feed full of machine gloss.', 'Hand-drawn ink illustration on warm off-white paper with visible tooth. Confident but imperfect linework — wobbling contours, varying line weight, the occasional overshoot left in. Sparse grey ink-wash shading and one restrained accent colour applied loosely outside the lines. Composition sits like a sketchbook page: generous margins, elements breathing, a few construction marks faintly visible.', 'Drawn with a few economical lines — hair, glasses and posture carry the likeness; faces are simple and expressive, never rendered.', 'vector cleanliness, digital brushes with perfect pressure, full colour fills, photorealism', '["hand-drawn","ink","sketch","human"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_isometric_world', 'seed_team_house', 'isometric-world', 'Isometric World', 'A little diorama on a floating tile, drawn at exact 30-degree axonometric angles. The product-explainer classic.', 'Isometric 3D illustration at a strict 30-degree axonometric projection, no perspective convergence. Clean modelled geometry with flat-shaded faces and one soft global light giving each plane a distinct tone. Limited saturated palette on a plain light background, the whole scene sitting on a floating rounded platform tile with a soft drop shadow. Tiny believable details reward a second look, but every element stays legible at thumbnail size.', 'A small isometric figure with simplified geometry and proportions, identifiable by colour of clothing, hair shape and posture rather than facial detail.', 'camera perspective, photorealism, outlines, gradients within faces, cluttered edges', '["isometric","3d","diagram","tech"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_magazine_editorial', 'seed_team_house', 'magazine-editorial', 'Magazine Editorial', 'Clean magazine-grade photography with nothing themed about it. The neutral default when the card should read as real content, not clip art.', 'Editorial photography for a quality print magazine, shot on a 50mm lens at f/2.8 with soft directional window light and one white bounce. True-to-life colour, gentle contrast, clean whites, honest shadows. Composition follows a clear focal hierarchy with generous breathing room, styled like an art-directed feature spread rather than a snapshot. Subtle natural grain, no filters, no colour cast.', 'A real photograph of them — natural skin, natural light, relaxed unposed expression, wardrobe an ordinary person would wear. No retouching sheen.', 'HDR, heavy grading, stock-photo posing, studio seamless backdrops, plastic skin, filters', '["photographic","editorial","neutral","clean"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_neubrutal_block', 'seed_team_house', 'neubrutal-block', 'Neubrutal Block', 'Raw blocks, thick borders, hard offset shadows, clashing colour. The anti-corporate signal beloved of dev tools and indie brands.', 'Neubrutalist graphic design: chunky rectangular blocks with thick uniform black borders and hard, unblurred offset shadows. Flat unblended colours that deliberately clash — acid yellow, cobalt, salmon — on a plain pale ground. Elements sit slightly misaligned, like a layout that refuses to be polished. No rounded corners bigger than a coin, no gradients, no transparency; everything is opaque, flat and emphatic.', 'Drawn as a flat sticker-like figure with a thick black outline and hard shadow, dropped onto the composition like a cut-out.', 'soft shadows, gradients, glassy surfaces, tasteful muted palettes, photographic elements', '["neubrutalism","graphic","bold","indie"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_paper_cut', 'seed_team_house', 'paper-cut', 'Paper Cut', 'Layered cut-paper collage with real depth and soft shadows. Tactile and warm — craft you can almost touch.', 'Layered paper-cut craft: every element cut from matte coloured card and stacked in physical layers, each casting a small soft shadow on the layer below. Slightly imperfect scissor edges, visible paper thickness at the cuts, and a gentle top-down light. A harmonious palette of five or six card colours, with background depth built from two or three receding paper planes. The whole scene reads as a photographed paper diorama.', 'Built from cut paper shapes — hair one piece, glasses another — with the likeness carried by shape and colour, layered so they stand slightly proud of the background.', 'flat vector look, digital gradients, glossy surfaces, photographic elements, hard shadows', '["paper","craft","tactile","layered"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_pixel_arcade', 'seed_team_house', 'pixel-arcade', 'Pixel Arcade', 'Chunky 16-bit pixel art with a limited palette. Instant nostalgia; great for dev and gaming-adjacent posts.', '16-bit era pixel art on a strict grid: chunky visible pixels, a limited palette of about sixteen colours, and dithering used sparingly for gradients. Clean single-pixel outlines where forms meet, flat colour fills inside, and a background built from simple parallax bands. The image is crisp — every pixel deliberate, no anti-aliasing blur, no mixels of different resolutions in one frame.', 'A pixel-art character at readable sprite scale — hair, glasses and outfit colours carry the likeness; the face is a few well-chosen pixels.', 'smooth gradients, anti-aliasing, 3D rendering, mixed pixel densities, photographic detail', '["pixel","retro","game","16-bit"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_pop_print', 'seed_team_house', 'pop-print', 'Pop Print', 'Screen-print pop art with Ben-Day dots and heavy outlines. Attention-grabbing, loud on purpose.', 'Classic pop-art screen print: bold flat primary colours laid in slightly misregistered layers, heavy black outlines, and Ben-Day halftone dots filling the mid-tones. High contrast, poster-flat space with a single graphic background colour, and one exaggerated focal element scaled up for punch. Ink sits matte on the surface with tiny print imperfections at the edges.', 'Drawn as a screen-printed portrait — strong outline, halftone shading on the face, hair as one flat shape, expression bold and theatrical.', 'gradients, soft shadows, photorealism, muted palettes, clean vector smoothness', '["pop-art","halftone","bold","print"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_quiet_minimal', 'seed_team_house', 'quiet-minimal', 'Quiet Minimal', 'One or two elements, vast emptiness, restrained colour. For cards where the headline does the talking and the picture just sets a tone.', 'Extreme minimalism: a single subject rendered small against a vast, evenly lit field of one muted colour. Matte finish, soft shadowless light, at most two tones plus a neutral. Composition places the subject far off-centre on a rule-of-thirds point, with the rest of the frame deliberately, luxuriously empty. No texture, no scenery, no props beyond the one that matters.', 'A small, simply rendered figure — clean shapes, soft matte shading — readable at a glance, defined by silhouette and one gesture.', 'clutter, gradients, dramatic lighting, patterns, more than three colours, backgrounds', '["minimal","calm","negative-space"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_single_line', 'seed_team_house', 'single-line', 'Single Line', 'One continuous contour line on a plain ground. Elegant, technical, almost empty — for refined tech and editorial spots.', 'Minimal contour line art: a single uniform-weight line describing the whole subject in one near-continuous stroke, monochrome ink on a plain warm-white ground. No fills, no shading, no crosshatching — at most one small solid accent dot of colour where the eye should land. The line economises ruthlessly, capturing form with the fewest possible bends, and the composition floats small in generous space.', 'Reduced to a continuous-line portrait — one stroke finds the hair, glasses and jaw; identity lives entirely in the silhouette the line describes.', 'varying line weight, sketch construction lines, fills, shadows, backgrounds, colour fields', '["line-art","minimal","elegant","mono"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_soft_3d', 'seed_team_house', 'soft-3d', 'Soft 3D', 'Friendly rounded 3D render — the look that replaced flat corporate illustration across SaaS marketing. Approachable but premium.', 'Polished 3D render with smooth, rounded, slightly inflated forms and softly bevelled edges. Matte-to-satin surfaces, no hard gloss. Big soft studio lighting with gentle ambient occlusion and one pastel-tinted fill, floating on a seamless pastel ground with a soft contact shadow. Palette of two or three pastels plus one saturated hero colour. Everything sits in calm, deliberate arrangements with lots of negative space.', 'A stylised 3D character with simplified friendly proportions and matte skin, recognisable by hair, build and glasses rather than photoreal facial detail.', 'photorealism, hard reflections, clay fingerprints, cartoon outlines, busy backgrounds', '["3d","soft","saas","friendly"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_watercolour_wash', 'seed_team_house', 'watercolour-wash', 'Watercolour Wash', 'Translucent washes and bleeding edges on textured paper. Warmth and approachability without a single hard line.', 'Traditional watercolour on cold-press paper, the grain showing through every wash. Translucent layered colour with soft bleeding edges, deliberate blooms where wet met wet, and dry-brush texture on the last pass. A light, airy palette with plenty of paper left white; edges of the image fade out rather than ending. One or two pencil underdrawing lines remain faintly visible under the paint.', 'Painted loosely — features suggested with a few darker touches, likeness carried by hair colour, glasses and posture, skin left as a pale wash.', 'digital gradients, hard outlines, saturated poster colour, photorealism, black shadows', '["watercolour","painted","warm","airy"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
INSERT INTO style (id, team_id, slug, name, description, look, subject, avoid, tags, origin, created_at, updated_at) VALUES ('seed_style_y2k_chrome', 'seed_team_house', 'y2k-chrome', 'Y2K Chrome', 'Liquid chrome, holographic sheen and millennium-bug optimism. The retro-future look trending back through fashion and consumer social.', 'Y2K retro-futurism: liquid chrome and iridescent surfaces reflecting a gradient sky of silver, baby blue and pink. Soft low-poly artifacts and a faint scanline shimmer nod to early CGI without breaking the render. Lens flares are small, star-shaped and sincere. Everything is glossy, curved and optimistic, floating in a bright airbrushed space with a horizon glow.', 'Rendered with a subtle holographic sheen on clothing and hair highlights, like an early 2000s album-cover portrait — glossy but still clearly them.', 'grunge, matte surfaces, dark cyberpunk palettes, film grain, brutalist typography shapes', '["y2k","chrome","iridescent","retro-future"]', 'hand', '2026-08-16T10:30:09.577Z', '2026-08-16T10:30:09.577Z');
